public class Main {
    public static void main(String[] args) {
        int score = 72;
        int goal = 100;
        System.out.println("score >= 50: " + (score >= 50));
        System.out.println("score == goal: " + (score == goal));
        System.out.println("score < goal: " + (score < goal));
        if (score >= 50) {
            System.out.println(score + " passed");
        }
        if (score == goal) {
            System.out.println(score + " is perfect");
        }

        score = 100;
        if (score >= 50) {
            System.out.println(score + " passed");
        }
        if (score == goal) {
            System.out.println(score + " is perfect");
        }
    }
}

